package com.tuowei.erp.masterdata.customerproduct.controller;
import com.tuowei.erp.common.security.PermissionCodes; import com.tuowei.erp.common.web.ApiResponse; import com.tuowei.erp.masterdata.customerproduct.service.CustomerProductRelationService; import com.tuowei.erp.masterdata.customerproduct.web.CustomerProductRelationRequest; import com.tuowei.erp.masterdata.customerproduct.web.CustomerProductRelationResponse; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/masterdata/customers/{customerId}/products") public class CustomerProductRelationController { private final CustomerProductRelationService service; public CustomerProductRelationController(CustomerProductRelationService service){this.service=service;} @PreAuthorize(PermissionCodes.HAS_MASTERDATA_CUSTOMER_VIEW) @GetMapping public ApiResponse<List<CustomerProductRelationResponse>> list(@PathVariable Long customerId){return ApiResponse.success(service.list(customerId));} @PreAuthorize(PermissionCodes.HAS_MASTERDATA_CUSTOMER_UPDATE) @PostMapping public ApiResponse<CustomerProductRelationResponse> save(@PathVariable Long customerId,@Valid @RequestBody CustomerProductRelationRequest request){return ApiResponse.success(service.save(customerId,request));} @PreAuthorize(PermissionCodes.HAS_MASTERDATA_CUSTOMER_UPDATE) @DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable Long customerId,@PathVariable Long id){service.delete(customerId,id);return ApiResponse.success(null);} }
